    len_ = len(input_string)
    if len_ == 1:
        return eval(input_string[0])
    if len_ == 2 and input_string[0] == 'Z':
        return intfrombase20(input_string[1]) + 26
    if len_ == 2 and input_string[1] in ('0','1','Z') and input_string[0] in ('0','1','Z'):
        if len(input_string) == 3:
            if input_string[2] == '=':
                return int(input_string[0]+input_string[1],2)
            else:
                return eval(input_string[0]+input_string[1]+input_string[2])
