            return 4096
        if input_string[1] == '0' and (input_string[0] == 'Z' or input_string[0] == '='):
            return 1
        if input_string[0] == '0' and (input_string[1] == 'Z' or input_string[1] == '='):
            return 20
        if input_string[1] == '0' and input_string[0] == '=':
            return int(input_string[0]+input_string[2],2)
